  db.companies.forEach(c => { c.contactName ||= c.name; c.contactEmail ||= `hello@${c.name.toLowerCase().replace(/[^a-z0-9]+/g, "")}.ai`; c.contactPhone ||= "Available after enquiry"; c.website ||= ""; });
  if (window.SaqrFilmDemo?.enabled) return;
  const add = (product, companyId) => { if (!db.products.some(p => p.id === product.id)) db.products.push({ ...product, companyId }); };
