function originalContent(value) { return `<span data-no-translate dir="auto">${esc(value)}</span>`; }
function detectContentLanguage(text) { return /\p{Script=Han}/u.test(text)?'zh':/\p{Script=Arabic}/u.test(text)?'ar':'en'; }
function renderMarkdown(value) { const source=String(value||"").replace(/\r/g,""); const html=window.marked && window.DOMPurify ? DOMPurify.sanitize(marked.parse(source, {gfm:true,breaks:true}), {FORBID_TAGS:['img','style','iframe','form'],FORBID_ATTR:['style']}) : `<p>${esc(source).replace(/\n/g,'<br>')}</p>`; return `<div class="markdown-body">${html}</div>`; }
function agentMarkdown(result) { if (!result) return ""; if (result.markdown) return result.markdown; const lines=[]; if(result.summary) lines.push(`## Summary\n${result.summary}`); if(result.matches?.length) lines.push(`### Matching products\n${result.matches.map(x=>`- **${x.name||x.product}** · ${x.provider||""} · USD ${x.monthly||"—"}/month · evidence ${x.evidence||"—"}%`).join("\n")}`); if(result.comparison?.length) lines.push(`### Decision rationale\n${result.comparison.map(x=>`- ${x.product||x.name}: ${x.reason||JSON.stringify(x)}`).join("\n")}`); if(result.decision_rationale?.length) lines.push(`### Decision rationale\n${result.decision_rationale.map(x=>`- ${typeof x==="string"?x:JSON.stringify(x)}`).join("\n")}`); if(result.insights?.length) lines.push(`### Insights\n${result.insights.map(x=>`- ${typeof x==='string'?x:JSON.stringify(x)}`).join("\n")}`); if(result.actions?.length) lines.push(`### Next actions\n${result.actions.map(x=>`- ${typeof x==='string'?x:JSON.stringify(x)}`).join("\n")}`); if(result.risks?.length) lines.push(`### Risks\n${result.risks.map(x=>`- ${typeof x==='string'?x:JSON.stringify(x)}`).join("\n")}`); return lines.join("\n\n"); }

