      return `<div class="order-row ${state.focusedOrderId === order.id ? 'focused-order' : ''}" data-order-id="${esc(order.id)}"><strong>${esc(order.id)}<small>${esc(order.orderedAt)}</small></strong><span><button class="order-product-link" data-product="${esc(order.productId)}" dir="auto">${esc(product?.name || order.title)}</button><small class="order-next-step" dir="auto">${esc(SaqrDB.orderText(order.nextStep, 'nextStep', state.lang))}</small>${checkoutOrderMeta(order)}</span><span dir="auto">${esc(other?.name || '')}</span>${orderStatus(order.status)}<strong dir="ltr">${money(order.total)}</strong></div>`;
