  const totals=products.map(p=>({product:p,orders:rows.filter(o=>o.productId===p.id)})).map(x=>({...x,value:x.orders.reduce((n,o)=>n+Number(o.total||0),0)})), states=[...new Set(rows.map(o=>o.status))];
