// Keep source attributes and text so persistent navigation always switches back cleanly.
const translationSources = new WeakMap();
function translate() {
  const dict = { ...(lang[state.lang] || {}), ...(phraseTranslations[state.lang] || {}) };
  const keys = Object.keys(dict).filter(Boolean).sort((a, b) => b.length - a.length);
  const pattern = keys.length ? new RegExp(keys.map(key => key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|"), "g") : null;
  const replace = value => pattern ? value.replace(pattern, key => dict[key]) : value;
  const apply = (node, key, value, write) => {
    const sources = translationSources.get(node) || {};
    const prior = sources[key];
    const source = prior && prior.rendered === value ? prior.source : value;
    const rendered = replace(source);
    sources[key] = { source, rendered };
    translationSources.set(node, sources);
    write(rendered);
  };
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(node => {
    // Messages and model responses are content, not interface labels.
    if (!node.parentElement?.closest('script, style, [data-no-translate], .chat-bubble, .chat-original, .assistant-message.user, .agent-bubble-body, .agent-history-title, .markdown-body')) {
      apply(node, 'text', node.nodeValue, value => { node.nodeValue = value; });
    }
  });
  $$('[placeholder], [aria-label], [title]').forEach(node => {
    ['placeholder', 'aria-label', 'title'].forEach(attribute => {
      if (node.hasAttribute(attribute)) apply(node, attribute, node.getAttribute(attribute), value => node.setAttribute(attribute, value));
    });
  });
}
// Old records may predate the language field. Detect those without changing saved data.
function reportLanguage(record) {
  const content = record.report || record.result || record;
  const explicit = record.language || content.language;
  if (explicit) return explicit;
  const text = JSON.stringify({ markdown: content.markdown, summary: content.summary, criteria: content.criteria, insights: content.insights, actions: content.actions });
  return /\p{Script=Han}/u.test(text) ? 'ZH' : /\p{Script=Arabic}/u.test(text) ? 'SA' : 'EN';
}
